1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Ledgerly Invoices</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #f5f6f8; color: #1f2530 }
10	  header { background: #fff; border-bottom: 1px solid #e4e7ec; padding: 16px 32px; display: flex; justify-content: space-between; align-items: center }
11	  .logo { font-weight: 700 }
12	  header a { font-size: 14px; color: #2456c4 }
13	  main { max-width: 680px; margin: 40px auto; padding: 0 24px }
14	  h1 { font-size: 24px; margin: 0 0 8px }
15	  p.sub { color: #525c69; margin: 0 0 24px }
16	  table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e4e7ec; border-radius: 8px }
17	  th, td { text-align: left; padding: 12px 16px; font-size: 14px; border-bottom: 1px solid #edeff3 }
18	  th { color: #5b6571 }
19	  .toolbar { margin: 20px 0 }
20	  .toolbar button { padding: 11px 18px; background: #2456c4; color: #fff; border: 0; border-radius: 7px; font-size: 14px; font-weight: 600; cursor: pointer }
21	  .overlay { position: fixed; inset: 0; background: rgba(20, 24, 32, 0.5); display: none; pointer-events: auto }
22	  .overlay.open { display: block }
23	  .modal { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 380px; background: #fff; border-radius: 10px; padding: 26px; display: none }
24	  .modal.open { display: block }
25	  .modal h2 { font-size: 18px; margin: 0 0 14px }
26	  .modal input { width: 100%; padding: 10px 12px; margin-bottom: 14px; border: 1px solid #c6ccd4; border-radius: 6px; font-size: 14px }
27	  .modal .row { display: flex; gap: 10px; justify-content: flex-end }
28	  .modal .row .ghost { background: #eef0f3; color: #1f2530 }
29	  .modal .row button { padding: 10px 16px; border: 0; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; background: #2456c4; color: #fff }
30	  *:focus-visible { outline: 2px solid #2456c4; outline-offset: 2px }
31	</style>
32	<script>
33	  window.__activated = []
34	  document.addEventListener('click', function (e) {
35	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
36	    var name = hit ? hit.getAttribute('data-track') : null
37	    if (name) window.__activated.push(name)
38	  })
39	</script>
40	</head>
41	<body>
42	<header>
43	  <span class="logo">Ledgerly</span>
44	  <a href="#help" data-track="help-link">Help center</a>
45	</header>
46	<main>
47	  <h1>Invoices</h1>
48	  <p class="sub">Everything sent this quarter, newest first.</p>
49	  <div class="toolbar">
50	    <button type="button" data-track="open-modal">New invoice</button>
51	  </div>
52	  <table>
53	    <thead>
54	      <tr><th>Number</th><th>Client</th><th>Amount</th><th>Status</th></tr>
55	    </thead>
56	    <tbody>
57	      <tr><td>INV-1042</td><td>Northwind Traders</td><td>$2,400.00</td><td>Paid</td></tr>
58	      <tr><td>INV-1041</td><td>Fabrikam</td><td>$860.00</td><td>Sent</td></tr>
59	      <tr><td>INV-1040</td><td>Contoso</td><td>$1,150.00</td><td>Overdue</td></tr>
60	    </tbody>
61	  </table>
62	  <p id="help" style="font-size: 13px; color: #545e6b">Need a hand? The help center covers numbering, taxes and reminders.</p>
63	</main>
64	<div class="overlay" id="overlay"></div>
65	<div class="modal" id="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" data-modal-root>
66	  <h2 id="modal-title">New invoice</h2>
67	  <input type="text" aria-label="Client name" placeholder="Client name">
68	  <input type="text" aria-label="Amount" placeholder="Amount">
69	  <div class="row">
70	    <button type="button" class="ghost" data-track="cancel-modal">Cancel</button>
71	    <button type="button" data-track="create-invoice">Create</button>
72	  </div>
73	</div>
74	<script>
75	  var overlay = document.getElementById('overlay')
76	  var modal = document.getElementById('modal')
77	  var openButton = document.querySelector('[data-track="open-modal"]')
78	  var cancelButton = document.querySelector('[data-track="cancel-modal"]')
79	  var createButton = document.querySelector('[data-track="create-invoice"]')
80	  var lastActiveElement = null
81	
82	  function getFocusableElements() {
83	    return modal.querySelectorAll('input, button')
84	  }
85	
86	  function handleTabKey(e) {
87	    var focusableElements = getFocusableElements()
88	    var firstElement = focusableElements[0]
89	    var lastElement = focusableElements[focusableElements.length - 1]
90	    var activeElement = document.activeElement
91	
92	    if (e.shiftKey) {
93	      if (activeElement === firstElement) {
94	        e.preventDefault()
95	        lastElement.focus()
96	      }
97	    } else {
98	      if (activeElement === lastElement) {
99	        e.preventDefault()
100	        firstElement.focus()
101	      }
102	    }
103	  }
104	
105	  function handleEscapeKey(e) {
106	    if (e.key === 'Escape') {
107	      closeModal()
108	    }
109	  }
110	
111	  function openModal() {
112	    lastActiveElement = document.activeElement
113	    overlay.classList.add('open')
114	    modal.classList.add('open')
115	    overlay.setAttribute('aria-hidden', 'true')
116	    overlay.style.pointerEvents = 'none'
117	    var firstFocusable = getFocusableElements()[0]
118	    if (firstFocusable) {
119	      firstFocusable.focus()
120	    }
121	    document.addEventListener('keydown', handleTabKey)
122	    document.addEventListener('keydown', handleEscapeKey)
123	  }
124	
125	  function closeModal() {
126	    overlay.classList.remove('open')
127	    modal.classList.remove('open')
128	    overlay.removeAttribute('aria-hidden')
129	    overlay.style.pointerEvents = ''
130	    document.removeEventListener('keydown', handleTabKey)
131	    document.removeEventListener('keydown', handleEscapeKey)
132	    if (lastActiveElement) {
133	      lastActiveElement.focus()
134	    }
135	  }
136	
137	  openButton.addEventListener('click', openModal)
138	  cancelButton.addEventListener('click', closeModal)
139	  createButton.addEventListener('click', closeModal)
140	</script>
141	</body>
142	</html>
